#!/usr/bin/env bash
set -u
echo "== 解包倍速工具更新 =="
mkdir -p /tmp/xm-speed && rm -rf /tmp/xm-speed/site && mkdir -p /tmp/xm-speed/site
echo '' | base64 -d > /tmp/xm-speed/u.tgz
tar -xzf /tmp/xm-speed/u.tgz -C /tmp/xm-speed/site
echo "== 覆盖到站点 =="
sudo cp -r /tmp/xm-speed/site/. /var/www/xinmo-site/
echo "== 校验 =="
grep -c 'AUTO_RESUME_KEY' /var/www/xinmo-site/tools/chaoxing-speed/chaoxing-speed.user.js
grep -o '@version      [0-9.]*' /var/www/xinmo-site/tools/chaoxing-speed/chaoxing-speed.user.js | head -1
echo "== DONE =="
